package recall

import "context"

// Gen is the nearline generative source (design §11 step 5): MiniOneRec's top items for the
// user, generated by the worker after the user's history changed and read in the same Redis
// round trip as the rest of the user context (Request.Gen). In process, so it never waits on a
// dependency; without a result it is not called (like SASRec for a cold-start user) and the
// fusion goes on with the other sources.
type Gen struct{}

func (Gen) Name() string { return "gen" }

// Applicable: only a request that came with a result has something to return.
func (Gen) Applicable(req Request) bool { return req.Gen != nil && len(req.Gen.Items) > 0 }

func (Gen) Recall(ctx context.Context, req Request) (Output, error) {
	g := req.Gen
	if g == nil {
		return Output{}, nil
	}
	n := min(req.K, len(g.Items))
	out := make([]Candidate, n)
	for i := 0; i < n; i++ {
		out[i] = Candidate{ItemID: g.Items[i], Score: g.Scores[i], Via: -1}
	}
	return Output{Items: out, Version: req.GenVersion}, ctx.Err()
}
